from __future__ import annotations

import io
import json
import tempfile
import unittest
from pathlib import Path
from typing import Any
from unittest import mock

from skill_picker import hook
from skill_picker.hook import last_assistant_text

SUGGESTION = {
    "name": "reproduce-bug",
    "description": "Create the smallest reliable reproduction.",
    "kind": "skill",
    "invocation": "/reproduce-bug",
    "relative_probability": 0.9,
    "fit_probability": 0.8,
}


def claude_line(role: str, text: str, **extra: Any) -> str:
    return json.dumps(
        {
            "type": role,
            "message": {"role": role, "content": [{"type": "text", "text": text}]},
            **extra,
        }
    )


def codex_line(role: str, text: str) -> str:
    block = "output_text" if role == "assistant" else "input_text"
    return json.dumps(
        {
            "type": "response_item",
            "payload": {
                "type": "message",
                "role": role,
                "content": [{"type": block, "text": text}],
            },
        }
    )


class LastAssistantTextTests(unittest.TestCase):
    def write(self, *lines: str) -> Path:
        directory = Path(self.enterContext(tempfile.TemporaryDirectory()))
        path = directory / "transcript.jsonl"
        path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        return path

    def test_reads_last_claude_code_reply(self) -> None:
        path = self.write(
            claude_line("assistant", "First reply."),
            claude_line("user", "Next question."),
            claude_line("assistant", "Pick option 1 or 2."),
        )

        self.assertEqual(last_assistant_text(path), "Pick option 1 or 2.")

    def test_reads_last_codex_reply(self) -> None:
        path = self.write(
            codex_line("assistant", "Old reply."),
            codex_line("user", "Continue."),
            codex_line("assistant", "Tests pass now."),
        )

        self.assertEqual(last_assistant_text(path), "Tests pass now.")

    def test_ignores_subagent_replies(self) -> None:
        path = self.write(
            claude_line("assistant", "Main thread reply."),
            claude_line("assistant", "Subagent chatter.", isSidechain=True),
        )

        self.assertEqual(last_assistant_text(path), "Main thread reply.")

    def test_skips_malformed_lines(self) -> None:
        path = self.write(
            claude_line("assistant", "Usable reply."),
            "{not json",
            json.dumps({"type": "assistant", "message": "unexpected"}),
        )

        self.assertEqual(last_assistant_text(path), "Usable reply.")

    def test_keeps_only_the_end_of_a_long_reply(self) -> None:
        path = self.write(claude_line("assistant", "a" * 5_000 + "END"))

        text = last_assistant_text(path)

        self.assertEqual(len(text), hook.CONTEXT_CHARS)
        self.assertTrue(text.endswith("END"))

    def test_missing_or_absent_transcript_gives_empty_context(self) -> None:
        self.assertEqual(last_assistant_text(Path("/no/such/transcript.jsonl")), "")
        self.assertEqual(last_assistant_text(None), "")


class HookMainTests(unittest.TestCase):
    def run_hook(
        self, stdin: str, result: dict[str, Any] | Exception | None = None
    ) -> tuple[int, str, mock.MagicMock]:
        stdout = io.StringIO()
        with mock.patch.object(hook, "pick") as pick:
            if isinstance(result, Exception):
                pick.side_effect = result
            else:
                pick.return_value = result or {"status": "ok", "suggestions": []}
            code = hook.main(io.StringIO(stdin), stdout)
        return code, stdout.getvalue(), pick

    def event(self, prompt: str, **extra: Any) -> str:
        return json.dumps(
            {"hook_event_name": "UserPromptSubmit", "prompt": prompt, **extra}
        )

    def test_suggestions_become_additional_context(self) -> None:
        code, output, _ = self.run_hook(
            self.event("Checkout hangs for some customers, find out why."),
            {"status": "ok", "suggestions": [SUGGESTION]},
        )

        self.assertEqual(code, 0)
        payload = json.loads(output)["hookSpecificOutput"]
        self.assertEqual(payload["hookEventName"], "UserPromptSubmit")
        self.assertIn("/reproduce-bug", payload["additionalContext"])
        self.assertIn(SUGGESTION["description"], payload["additionalContext"])

    def test_short_replies_never_reach_the_router(self) -> None:
        for prompt in ("yupp", "go on", "why this?", "  "):
            with self.subTest(prompt=prompt):
                code, output, pick = self.run_hook(self.event(prompt))

                self.assertEqual((code, output), (0, ""))
                pick.assert_not_called()

    def test_transcript_reply_is_passed_as_recent_context(self) -> None:
        directory = Path(self.enterContext(tempfile.TemporaryDirectory()))
        transcript = directory / "t.jsonl"
        transcript.write_text(claude_line("assistant", "Which option?") + "\n")

        _, _, pick = self.run_hook(
            self.event(
                "Use the second option please.", transcript_path=str(transcript)
            )
        )

        self.assertEqual(pick.call_args.kwargs["recent_context"], "Which option?")

    def test_results_without_suggestions_add_nothing(self) -> None:
        for result in (
            {"status": "ok", "suggestions": []},
            {"status": "skipped", "reason": "explicit_action_invocation", "suggestions": []},
            {"status": "unavailable", "reason": "no API key", "suggestions": []},
        ):
            with self.subTest(status=result["status"]):
                code, output, _ = self.run_hook(
                    self.event("Review the diff before I merge it."), result
                )

                self.assertEqual((code, output), (0, ""))

    def test_never_blocks_the_prompt_on_bad_input_or_errors(self) -> None:
        for stdin, result in (
            ("not json", None),
            (json.dumps(["not", "an", "object"]), None),
            (json.dumps({"prompt": 42}), None),
            (self.event("Review the diff before I merge it."), RuntimeError("boom")),
        ):
            with self.subTest(stdin=stdin[:20]):
                code, output, _ = self.run_hook(stdin, result)

                self.assertEqual((code, output), (0, ""))


if __name__ == "__main__":
    unittest.main()

