            },
        )
        if explicit:
            result = {
                "status": "skipped",
                "reason": "explicit_action_invocation",
                "suggestions": [],
            }
        elif api_key := resolve_api_key():
            result = recommend(
                request,
                skills,
                lambda payload: call_typesafe(
                    payload, api_key=api_key, timeout=timeout
                ),
                model=model,
                gate_floor=gate_floor,
                fit_floor=fit_floor,
                shortlist_size=shortlist_size,
                recent_context=recent_context,
            )
        else:
            result = {
                "status": "unavailable",
                "reason": _no_key_reason(),
                "suggestions": [],
            }
    except (KeyError, OSError, TypeError, ValueError, RouterUnavailable) as error:
        result = {
            "status": "unavailable",
            "reason": str(error),
            "suggestions": [],
        }

    print(json.dumps(result, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

